insert into lounge_topics(id,title,cat,body,sources,is_seed) values
('seed-01','Should the MRT/LRT be privatized or stay government-run?','Transport & Infrastructure','Supporters say private operators can fund maintenance and improve service; critics worry about fare hikes and weaker public accountability. The 2022 amendment to the Public Service Act changed which sectors count as ''public utilities'', which affects foreign participation in transport.','[{"title": "RA 11659 – Public Service Act amendments (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"}]'::jsonb,true),
('seed-02','Mining in the Sierra Madre: development or destruction?','Environment','The Sierra Madre is a major forest and watershed; mining is governed by the Philippine Mining Act. Debate centers on jobs and revenue versus forest loss, flooding risk and indigenous land rights. Check DENR and community sources for specific permits.','[{"title": "RA 7942 – Philippine Mining Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra1995/ra_7942_1995.html"}, {"title": "DENR", "url": "https://www.denr.gov.ph/"}]'::jsonb,true),
('seed-03','Is the government ready for El Niño and La Niña?','Disaster & Weather','Readiness questions include water supply, crop insurance, and local climate action plans required under the Climate Change Act. PAGASA issues the official ENSO advisories.','[{"title": "RA 9729 – Climate Change Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2009/ra_9729_2009.html"}, {"title": "PAGASA", "url": "https://www.pagasa.dost.gov.ph/"}]'::jsonb,true),
('seed-04','Peso vs US dollar: who wins and who loses when the peso weakens?','Economy & Jobs','A weaker peso raises the peso value of OFW remittances and exports, but makes imported fuel and food costlier. Use the live USD→PHP panel on the Civi map and BSP''s official reference rate.','[{"title": "Civi KPI panel (Frankfurter/ECB rates)", "url": "https://www.frankfurter.app/"}, {"title": "PSA OpenSTAT (inflation)", "url": "https://openstat.psa.gov.ph/"}]'::jsonb,true),
('seed-05','Should the Philippines legalize divorce?','Laws & Policy','The Philippines and Vatican City are commonly cited as the only states without general divorce law; annulment and legal separation exist under the Family Code. Divorce bills have been filed in several Congresses. Share the bill number you are discussing.','[{"title": "Family Code (LawPhil)", "url": "https://lawphil.net/executive/execord/eo1987/eo_209_1987.html"}]'::jsonb,true),
('seed-06','Jeepney modernization: phase out or upgrade?','Transport & Infrastructure','The PUV modernization program requires franchise consolidation and newer units. Drivers and operators raise costs and loans; commuters raise safety and emissions. Post official LTFRB/DOTr issuances when citing deadlines.','[{"title": "LTFRB", "url": "https://ltfrb.gov.ph/"}, {"title": "DOTr", "url": "https://dotr.gov.ph/"}]'::jsonb,true),
('seed-07','West Philippine Sea: diplomacy, alliances, or self-reliance?','Security','The 2016 arbitral award (PCA Case 2013-19) and the 2024 Philippine Maritime Zones Act are the key legal references. Debate covers how to assert rights while avoiding conflict.','[{"title": "PCA Case 2013-19", "url": "https://pca-cpa.org/en/cases/7/"}, {"title": "RA 12064 – Philippine Maritime Zones Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2024/ra_12064_2024.html"}]'::jsonb,true),
('seed-08','Maharlika Investment Fund: smart investment or risky bet?','Economy & Jobs','The fund was created by RA 11954 (2023). Discussion points: governance safeguards, where the seed capital came from, and transparency of returns.','[{"title": "RA 11954 – Maharlika Investment Fund Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2023/ra_11954_2023.html"}]'::jsonb,true),
('seed-09','SIM card registration: did it stop scams?','Security','RA 11934 requires SIM registration. Users can share experiences with scam texts since then; please don''t post anyone''s personal numbers.','[{"title": "RA 11934 – SIM Registration Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11934_2022.html"}]'::jsonb,true),
('seed-10','Is the new procurement law enough to stop corruption?','Government','RA 12009 (2024) revised the Government Procurement Reform Act. PhilGEPS publishes bid notices that anyone can check.','[{"title": "RA 12009 – New Government Procurement Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2024/ra_12009_2024.html"}, {"title": "PhilGEPS", "url": "https://notices.philgeps.gov.ph/"}]'::jsonb,true),
('seed-11','Where does our national budget go?','Government','DBM publishes the General Appropriations Act and budget documents. Pick a department and compare allocations year to year.','[{"title": "DBM", "url": "https://www.dbm.gov.ph/"}]'::jsonb,true),
('seed-12','Flood control projects: are they working in your area?','Transport & Infrastructure','Share photos (no faces), locations and official project pages. DPWH lists projects; compare with what you see on the ground.','[{"title": "DPWH", "url": "https://www.dpwh.gov.ph/"}]'::jsonb,true),
('seed-13','Online scams and cybercrime: what actually helps?','Security','The Cybercrime Prevention Act (RA 10175) is the main law. Share verified reporting channels and prevention tips; never share victims'' details.','[{"title": "RA 10175 – Cybercrime Prevention Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2012/ra_10175_2012.html"}]'::jsonb,true),
('seed-14','Data privacy: do apps and agencies protect our data?','Laws & Policy','RA 10173 gives you rights to be informed, access, correct and erase personal data. The National Privacy Commission handles complaints.','[{"title": "RA 10173 – Data Privacy Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2012/ra_10173_2012.html"}, {"title": "National Privacy Commission", "url": "https://privacy.gov.ph/"}]'::jsonb,true),
('seed-15','Ease of doing business: is red tape really lower?','Government','RA 11032 set processing-time limits for government transactions and created ARTA. Share your real experience (time, office, outcome).','[{"title": "RA 11032 – Ease of Doing Business Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"}]'::jsonb,true),
('seed-16','Electric vehicles: realistic for Filipino roads?','Environment','RA 11697 (2022) is the EV Industry Development Act. Topics: charging stations, prices, power supply.','[{"title": "RA 11697 – EVIDA (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2022/ra_11697_2022.html"}]'::jsonb,true),
('seed-17','Child marriage ban: how is it enforced?','Laws & Policy','RA 11596 (2021) prohibits child marriage. Discuss awareness and enforcement in communities.','[{"title": "RA 11596 (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2021/ra_11596_2021.html"}]'::jsonb,true),
('seed-18','Reproductive health: is the RH Law fully implemented?','Health','RA 10354 (2012) set a national policy on responsible parenthood and reproductive health. Share local access experiences.','[{"title": "RA 10354 – RH Law (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2012/ra_10354_2012.html"}]'::jsonb,true),
('seed-19','Vaping and tobacco: stricter rules needed?','Health','RA 9211 (2003) regulates tobacco packaging and ads; later laws added vape rules. Share the specific rule you''re debating.','[{"title": "RA 9211 – Tobacco Regulation Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2003/ra_9211_2003.html"}]'::jsonb,true),
('seed-20','Fair competition: are prices high because of monopolies?','Economy & Jobs','RA 10667 created the Philippine Competition Commission. Discuss sectors where you see little choice.','[{"title": "RA 10667 – Philippine Competition Act (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra2015/ra_10667_2015.html"}]'::jsonb,true),
('seed-21','Should LGUs get more power and budget?','Government','The Local Government Code (RA 7160) defines LGU powers. Debate decentralization vs national oversight.','[{"title": "RA 7160 – Local Government Code (LawPhil)", "url": "https://lawphil.net/statutes/repacts/ra1991/ra_7160_1991.html"}]'::jsonb,true),
('seed-22','Rising prices: what''s hitting your household most?','Economy & Jobs','PSA publishes monthly inflation by commodity group. Share which items hurt most and where you live (city level only).','[{"title": "PSA OpenSTAT – CPI", "url": "https://openstat.psa.gov.ph/"}]'::jsonb,true),
('seed-23','Jobs: is underemployment the real problem?','Economy & Jobs','PSA''s Labor Force Survey reports unemployment and underemployment rates monthly. Share what kind of work is available near you.','[{"title": "PSA OpenSTAT – Labor Force Survey", "url": "https://openstat.psa.gov.ph/"}]'::jsonb,true),
('seed-24','Education: what should DepEd fix first?','Education','Common topics: classroom shortage, learning recovery, teacher workload, curriculum. Cite DepEd orders when possible.','[{"title": "DepEd", "url": "https://www.deped.gov.ph/"}]'::jsonb,true),
('seed-25','Gilas Pilipinas and PH sports funding: enough support for athletes?','Sports','Discuss funding, grassroots programs and facilities. Cite PSC or federation sources.','[{"title": "Philippine Sports Commission", "url": "https://psc.gov.ph/"}]'::jsonb,true),
('seed-26','OPM and local films: how do we support Filipino artists?','Entertainment','Talk about streaming, cinema quotas, festivals and piracy. Share links to official artist pages.','[{"title": "FDCP", "url": "https://www.fdcp.ph/"}]'::jsonb,true),
('seed-27','Disaster prep at barangay level: what does your barangay do?','Disaster & Weather','NDRRMC and local DRRM offices run preparedness. Share drills, evacuation centers and gaps (no personal info).','[{"title": "NDRRMC", "url": "https://ndrrmc.gov.ph/"}, {"title": "PHIVOLCS", "url": "https://www.phivolcs.dost.gov.ph/"}]'::jsonb,true),
('seed-28','Freedom of Information: should FOI become a law?','Laws & Policy','An FOI program for the executive branch exists via the eFOI portal; debate is whether Congress should pass an FOI law covering all branches.','[{"title": "eFOI portal", "url": "https://www.foi.gov.ph/"}]'::jsonb,true)
